sources=json.loads((ROOT/'locales/sources.json').read_text(encoding='utf-8'))
for code in ('en',*LANGS):
    p=ROOT/'locales'/f'{code}.json';catalog=json.loads(p.read_text(encoding='utf-8'));messages=catalog['messages']
    for key in sources:
        if code=='en':messages[key]=key
        elif key in M:messages[key]=M[key][LANGS.index(code)]
        elif key not in messages:raise ValueError('Missing translation: '+code+' '+key)
    p.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
